  databaseHelp: ['Banco local de contatos. Tudo fica neste computador.', 'Local contact database. Everything stays on this computer.', 'Base local de contactos. Todo queda en este equipo.'], clearByCall: ['Limpar banco por indicativo', 'Clear database by callsign', 'Limpiar base por indicativo'], clearByCallHelp: ['Marque os indicativos de estação (STATION_CALLSIGN) cujos QSOs devem ser apagados. Os demais permanecem intactos.', 'Check the station callsigns (STATION_CALLSIGN) whose QSOs should be deleted. Others remain untouched.', 'Marque los indicativos de estación cuyos QSOs deben eliminarse. Los demás permanecen intactos.'], restrictContainer: ['Restringir ao container', 'Restrict to container', 'Restringir al contenedor'], deleteSelectedCalls: ['Apagar QSOs dos indicativos marcados', 'Delete QSOs of checked callsigns', 'Eliminar QSOs de los indicativos marcados'], selectCalls: ['Marque ao menos um indicativo', 'Check at least one callsign', 'Marque al menos un indicativo'], confirmDeleteCalls: ['Apagar todos os QSOs de {calls}?', 'Delete all QSOs of {calls}?', '¿Eliminar todos los QSOs de {calls}?'], removedN: ['{n} QSOs removidos', '{n} QSOs removed', '{n} QSOs eliminados'],
  countryFile: ['Country-File (CTY.DAT)', 'Country-File (CTY.DAT)', 'Country-File (CTY.DAT)'], countryFileHelp: ['Versão atual: {v}. Baixe o arquivo mais recente em country-files.com (AD1C) e carregue aqui; depois use Logs → Modificar logs para atualizar QSOs antigos.', 'Current version: {v}. Download the latest file from country-files.com (AD1C) and load it here; then use Logs → Modify logs to update older QSOs.', 'Versión actual: {v}. Descargue el archivo más reciente en country-files.com (AD1C) y cárguelo aquí; luego use Logs → Modificar logs.'], loadCty: ['Carregar CTY.DAT', 'Load CTY.DAT', 'Cargar CTY.DAT'], resetCty: ['Usar o CTY.DAT embutido', 'Use built-in CTY.DAT', 'Usar el CTY.DAT incluido'], invalidCty: ['Arquivo CTY.DAT inválido', 'Invalid CTY.DAT file', 'Archivo CTY.DAT inválido'], ctyLoaded: ['Country-File carregado (versão {v})', 'Country-File loaded (version {v})', 'Country-File cargado (versión {v})'],
  clearAll: ['Apagar todos os QSOs', 'Delete all QSOs', 'Eliminar todos los QSOs'], clearAllHelp: ['Remove todos os contatos. Preferências, notas e configurações são mantidas.', 'Removes all contacts. Preferences, notes and settings are kept.', 'Elimina todos los contactos. Se conservan preferencias, notas y configuración.'], confirmClearAll: ['Apagar TODOS os QSOs do banco?', 'Delete ALL QSOs from the database?', '¿Eliminar TODOS los QSOs de la base?'], confirmAgain: ['Tem certeza? Esta ação não pode ser desfeita.', 'Are you sure? This cannot be undone.', '¿Seguro? Esta acción no se puede deshacer.'], factoryReset: ['Reiniciar de fábrica', 'Factory reset', 'Restablecer de fábrica'], factoryResetHelp: ['Apaga banco, preferências, credenciais salvas e Country-File carregado e reabre o aplicativo como na primeira execução.', 'Erases database, preferences, saved credentials and loaded Country-File and reopens the app as on first run.', 'Borra base, preferencias, credenciales y Country-File cargado y reabre la aplicación como en la primera ejecución.'], confirmFactoryReset: ['Apagar TODOS os dados locais e reiniciar?', 'Erase ALL local data and restart?', '¿Borrar TODOS los datos locales y reiniciar?'], confirmDeleteContainer: ['Excluir o container "{name}" e todos os seus QSOs?', 'Delete container "{name}" and all its QSOs?', '¿Eliminar el contenedor "{name}" y todos sus QSOs?'],
