  newVersionTitle: ['Nova versão disponível', 'New version available', 'Nueva versión disponible'], newVersionMessage: ['A versão {v} está disponível em www.pt2vhf.com (você usa a {current}). Seus dados locais são preservados na atualização.', 'Version {v} is available at www.pt2vhf.com (you have {current}). Your local data is kept when updating.', 'La versión {v} está disponible en www.pt2vhf.com (usted tiene la {current}). Sus datos locales se conservan al actualizar.'], later: ['Depois', 'Later', 'Después'], openDownloadPage: ['Abrir página de download', 'Open download page', 'Abrir página de descarga'], updateCheckFailed: ['Não foi possível consultar www.pt2vhf.com', 'Could not reach www.pt2vhf.com', 'No se pudo consultar www.pt2vhf.com'],
