  health_missingBand: ['Sem banda', 'Missing band', 'Sin banda'], healthHelp_missingBand: ['QSOs sem banda; quando há frequência, a banda pode ser calculada.', 'QSOs without band; when there is a frequency, the band can be computed.', 'QSOs sin banda; cuando hay frecuencia, la banda puede calcularse.'],
  health_nearDupes: ['Duplicados próximos', 'Near duplicates', 'Duplicados cercanos'], healthHelp_nearDupes: ['Mesmo indicativo, banda e modo a até 3 minutos de outro QSO: provável registro em dobro.', 'Same call, band and mode within 3 minutes of another QSO: probably logged twice.', 'Mismo indicativo, banda y modo a menos de 3 minutos de otro QSO: probablemente registrado dos veces.'],
  health_typos: ['Indicativos possivelmente errados', 'Possibly mistyped callsigns', 'Indicativos posiblemente erróneos'], healthHelp_typos: ['Indicativos que aparecem uma vez e diferem em um caractere de outro frequente na mesma banda (ex.: PT2VFH × PT2VHF).', 'Callsigns that appear once and differ by one character from a frequent one on the same band (e.g. PT2VFH × PT2VHF).', 'Indicativos que aparecen una vez y difieren en un carácter de otro frecuente en la misma banda (p. ej. PT2VFH × PT2VHF).'],
