export const MESSAGES = Object.fromEntries(LANGUAGES.map(l => [l.code, Object.fromEntries(Object.entries(M).map(([k, v]) => [k, v[IDX[l.code]] ?? v[0]]))]));

export function translate(lang, key, vars) {
  const text = MESSAGES[lang]?.[key] ?? MESSAGES['pt-BR'][key] ?? key;
  return vars ? text.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? '')) : text;
}
